/**
 * Feature Merger Utility
 * 
 * Merges master features from ULS package with custom features from user's project.
 * Validates for duplicate IDs and provides safe merging.
 * 
 * @param {Array} masterFeatures - Features from ULS package
 * @param {Array} customFeatures - Features from user's custom-demo folder
 * @param {Object} options - Merge options
 * @returns {Array} Merged features array
 */
export function mergeFeatures(masterFeatures = [], customFeatures = [], options = {}) {
    const {
        duplicateHandling = 'filter', // 'filter' | 'prefix' | 'error'
        prefix = 'custom-',
        validate = true
    } = options;

    if (!customFeatures || customFeatures.length === 0) {
        return masterFeatures;
    }

    // Validate no duplicate IDs
    const masterIds = new Set(masterFeatures.map(f => f.id));
    const duplicates = customFeatures.filter(f => masterIds.has(f.id));

    if (validate && duplicates.length > 0) {
        switch (duplicateHandling) {
            case 'error':
                throw new Error(
                    `Duplicate feature IDs not allowed: ${duplicates.map(f => f.id).join(', ')}`
                );

            case 'prefix':
                const prefixedCustom = customFeatures.map(feature =>
                    masterIds.has(feature.id)
                        ? { ...feature, id: `${prefix}${feature.id}` }
                        : feature
                );
                return [...masterFeatures, ...prefixedCustom];

            case 'filter':
            default:
                console.warn(
                    `⚠️  Duplicate feature IDs found: ${duplicates.map(f => f.id).join(', ')}. ` +
                    `Custom features with duplicate IDs will be filtered out.`
                );
                customFeatures = customFeatures.filter(f => !masterIds.has(f.id));
                break;
        }
    }

    // Merge: Insert custom features before Accessibility (last master feature)
    // Find the index of Accessibility feature (if exists)
    const accessibilityIndex = masterFeatures.findIndex(f => 
        f.id && (f.id.toLowerCase() === 'accessibility' || f.sectionNav && f.sectionNav.toLowerCase() === 'accessibility')
    );
    
    if (accessibilityIndex !== -1) {
        // Insert custom features before Accessibility
        return [
            ...masterFeatures.slice(0, accessibilityIndex),
            ...customFeatures,
            ...masterFeatures.slice(accessibilityIndex)
        ];
    }
    
    // If no Accessibility found, append custom features at the end
    return [...masterFeatures, ...customFeatures];
}

/**
 * Diff two feature arrays to find changes
 * @param {Array} oldFeatures - Previous features
 * @param {Array} newFeatures - New features
 * @returns {Object} Diff object with added, removed, and modified arrays
 */
export function diffFeatures(oldFeatures = [], newFeatures = []) {
    const oldMap = new Map(oldFeatures.map(f => [f.id, f]));
    const newMap = new Map(newFeatures.map(f => [f.id, f]));

    const added = [];
    const removed = [];
    const modified = [];

    // Find new features
    newFeatures.forEach(feature => {
        if (!oldMap.has(feature.id)) {
            added.push(feature);
        } else {
            // Check if modified
            const old = oldMap.get(feature.id);
            if (JSON.stringify(old) !== JSON.stringify(feature)) {
                modified.push({ old, new: feature });
            }
        }
    });

    // Find removed features
    oldFeatures.forEach(feature => {
        if (!newMap.has(feature.id)) {
            removed.push(feature);
        }
    });

    return {
        added,
        removed,
        modified,
        hasChanges: added.length > 0 || removed.length > 0 || modified.length > 0
    };
}

